questionvariables.text:
var_1:rand(10)+1;
var_2:var_1^2;
val_limit:rand(3);
var_letter:rand([x,y,t,z,r]);
eqn_1:(sqrt(var_letter^2+var_2)-var_1)/(var_letter^2);
eqn_2:(var_letter-var_1)/(var_letter^2-var_2);
eqn:rand([eqn_1,eqn_2]);

num_eqn:num(eqn);
den_eqn:denom(eqn); 
den_eqn_limit: at(den_eqn, [var_letter=val_limit]);
den_eqn_1:factor(den_eqn);
sol_1:num_eqn/den_eqn_1;/*the simplified form of the equation*/
sol_a:subst(val_limit,var_letter,eqn_1);
sol_b:1/(sqrt(val_limit^2+var_2)+var_1)
ta_1:decimalplaces(sol_b,2)
sol_2:subst(val_limit,var_letter,sol_1);
ta_2:decimalplaces(sol_2,2);
if eqn = eqn_1 then ta: sol_b else ta:sol_2;
